class Solution:
    def maxRepOpt1(self, text: str) -> int:
        n = len(text)
        cnt = Counter(text)
        blocks = []
        i = 0
        while i < n:
            j = i
            while j < n and text[j] == text[i]:
                j += 1
            blocks.append((text[i], j - i))
            i = j
        ans = 0
        for k, (c, l) in enumerate(blocks):
            if cnt[c] > l:
                ans = max(ans, l + 1)
            else:
                ans = max(ans, l)
            if k > 0 and k + 1 < len(blocks) and blocks[k-1][0] == blocks[k+1][0]:
                s = blocks[k-1][1] + blocks[k+1][1]
                if cnt[blocks[k-1][0]] > s:
                    s += 1
                ans = max(ans, s)
        return ans

