class Solution {
public:
    int maxRepOpt1(string text) {
        int n = text.size();
        vector<int> cnt(26, 0);
        for (char ch : text) cnt[ch - 'a']++;
        vector<pair<char,int>> blocks;
        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && text[j] == text[i]) j++;
            blocks.push_back({text[i], j - i});
            i = j;
        }
        int ans = 0, m = blocks.size();
        for (int k = 0; k < m; k++) {
            char c = blocks[k].first;
            int l = blocks[k].second;
            ans = max(ans, cnt[c-'a'] > l ? l + 1 : l);
            if (k > 0 && k + 1 < m && blocks[k-1].first == blocks[k+1].first) {
                int s = blocks[k-1].second + blocks[k+1].second;
                if (cnt[c-'a'] > s) s++;
                ans = max(ans, s);
            }
        }
        return ans;
    }
};

