class Solution {
    public int maxRepOpt1(String text) {
        int n = text.length();
        int[] cnt = new int[26];
        for (char ch : text.toCharArray()) cnt[ch - 'a']++;
        List<int[]> blocks = new ArrayList<>();
        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && text.charAt(j) == text.charAt(i)) j++;
            blocks.add(new int[]{text.charAt(i) - 'a', j - i});
            i = j;
        }
        int ans = 0, m = blocks.size();
        for (int k = 0; k < m; k++) {
            int c = blocks.get(k)[0], l = blocks.get(k)[1];
            ans = Math.max(ans, cnt[c] > l ? l + 1 : l);
            if (k > 0 && k + 1 < m && blocks.get(k-1)[0] == blocks.get(k+1)[0]) {
                int s = blocks.get(k-1)[1] + blocks.get(k+1)[1];
                if (cnt[c] > s) s++;
                ans = Math.max(ans, s);
            }
        }
        return ans;
    }
}

