class Solution:
    def maxRepOpt1(self, text: str) -> int:
        cnt = Counter(text)
        win = defaultdict(int)
        ans = left = 0
        for right, ch in enumerate(text):
            win[ch] += 1
            while len(win) > 1 and (right - left + 1) - max(win.values()) > 1:
                win[text[left]] -= 1
                if win[text[left]] == 0:
                    del win[text[left]]
                left += 1
            major = max(win, key=win.get)
            ans = max(ans, min(right - left + 1, cnt[major]))
        return ans

