class Solution {
public:
    int maxRepOpt1(string text) {
        array<int,26> cnt{}, win{};
        for (char ch : text) cnt[ch-'a']++;
        int distinct = 0, ans = 0, left = 0;
        for (int right = 0; right < (int)text.size(); right++) {
            if (win[text[right]-'a']++ == 0) distinct++;
            int mf = *max_element(win.begin(), win.end());
            while ((right-left+1) - mf > 1) {
                if (--win[text[left]-'a'] == 0) distinct--;
                left++;
                mf = *max_element(win.begin(), win.end());
            }
            int mi = max_element(win.begin(), win.end()) - win.begin();
            ans = max(ans, min(right-left+1, cnt[mi]));
        }
        return ans;
    }
};

