class Solution {
    public int maxRepOpt1(String text) {
        int[] cnt = new int[26], win = new int[26];
        for (char ch : text.toCharArray()) cnt[ch - 'a']++;
        int ans = 0, left = 0;
        for (int right = 0; right < text.length(); right++) {
            win[text.charAt(right) - 'a']++;
            int mf = 0, mi = 0;
            do {
                mf = 0; mi = 0;
                for (int i = 0; i < 26; i++) if (win[i] > mf) { mf = win[i]; mi = i; }
                if ((right - left + 1) - mf <= 1) break;
                win[text.charAt(left) - 'a']--;
                left++;
            } while (true);
            ans = Math.max(ans, Math.min(right - left + 1, cnt[mi]));
        }
        return ans;
    }
}

